"""Assembles MACHINE_READABLE_RESULT.json: findings (from ANALYSIS_RESULTS + LITERATURE_EVIDENCE), reference zones,
VOCAL_KEY_OPTIMIZER spec, design-only scoring engine, ID/attribution chain, receipt. Design-only: no scoring is executed."""
import json, os, csv
